-- V1__create_users.sql
--
-- Flyway runs every file in this folder named V<number>__<description>.sql exactly once, in number
-- order, and records each in the flyway_schema_history table. NEVER edit a migration that has
-- already run anywhere: Flyway checks a checksum and refuses to start. To change the schema,
-- add a new file (V2__..., V3__...).
--
-- The Java side of this table is the User entity (added in Milestone 2).

CREATE TABLE users (
    -- UUIDs are generated by the application, so ids can be known before the INSERT and are not guessable.
    id            UUID         PRIMARY KEY,
    email         VARCHAR(255) NOT NULL,
    full_name     VARCHAR(100) NOT NULL,
    -- A bcrypt hash of the password. The real password is never stored.
    password_hash VARCHAR(100) NOT NULL,
    -- Plain text + CHECK instead of a PostgreSQL ENUM type: adding a role later is a one-line change
    -- to the CHECK, while altering an ENUM type is awkward inside a migration.
    role          VARCHAR(20)  NOT NULL CHECK (role IN ('CUSTOMER', 'ORGANIZER')),
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT now()
);

-- A UNIQUE index: two accounts can never share an e-mail, and e-mail lookups (login) are fast.
CREATE UNIQUE INDEX users_email_key ON users (email);
